<template>
  <section v-if="allowed" aria-label="全局手术资源身份与声明治理">
    <p>永久物理资源和账号关联不具有撤销状态。资源池、明确别名与成员声明独立审核/撤销；任何登记都不代替岗位资格、患者照护或资源可用性。</p>
    <p v-if="error" role="alert">{{ error }}</p>
    <el-form inline><el-form-item label="资源登记类型"><el-select v-model="registryKind" aria-label="资源登记类型"><el-option v-for="(label,key) in surgeryRegistryKinds" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-button :disabled="loading" @click="load">重新读取完整定位目录</el-button><el-button :disabled="loading" @click="beginCreate">建立明确新登记</el-button></el-form>
    <el-table v-loading="loading" :data="rows" row-key="registry_record_id"><el-table-column prop="registry_record_id" label="明确登记标识" min-width="220" /><el-table-column label="状态"><template #default="{row}">{{ row.governance?surgerySourceStates[row.governance.status]+' · v'+row.governance.revision:'永久技术身份锚' }}</template></el-table-column><el-table-column label="当前性"><template #default="{row}">{{ row.eligible_for_new_use?'当前父件及治理成立；用途另核':'当前仅审计' }}</template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button size="small" @click="inspect(row)">核对完整登记</el-button></template></el-table-column></el-table>
    <el-pagination v-if="total" v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="load" />
    <article v-if="selected" aria-label="完整资源登记核对"><h3>{{ surgeryRegistryKinds[selected.registry_kind] }} · {{ selected.payload?.label||selected.payload?.name||selected.registry_record_id }}</h3><p>完整原件SHA：{{ selected.content_hash }}</p><p v-if="selected.governance_hash">独立治理SHA：{{ selected.governance_hash }}</p><p v-if="!selected.eligible_for_new_use">当前不可用于新声明：{{ selected.exclusion_reasons.join('；') }}。</p><el-input :model-value="JSON.stringify(selected,null,2)" aria-label="完整院内资源登记原件" type="textarea" :rows="14" readonly />
      <p><el-button v-if="selected.registry_kind==='pool'" @click="$emit('pool-selected',{pool_id:selected.pool_id})">查看此资源池所有来源</el-button><el-button v-if="selected.can_review===true" @click="beginAction('publish')">审核发布此声明</el-button><el-button v-if="selected.can_review===true" @click="beginAction('reject')">审核拒绝此声明</el-button><el-button v-if="selected.can_revoke===true" type="danger" @click="beginAction('revoke')">按原版本撤销此声明</el-button></p>
    </article>
    <el-dialog :model-value="creating" title="建立明确资源登记" width="min(1000px,96vw)" @update:model-value="value=>!value&&closeCreate()"><template v-if="creating"><p>原科室与账号按明确分页完整读取，设备按实际身份目录选择；目录不证明岗位资格或资源覆盖。</p><p>{{ directories?.cssd_scope }}</p><el-form inline><el-form-item label="CSSD原包名或编号检索"><el-input v-model="cssdKeyword" aria-label="CSSD原包名或编号检索" /></el-form-item><el-button :disabled="loading" @click="readDirectories">重新检索原CSSD候选</el-button></el-form>
      <SurgeryFields v-if="schema" :key="registryKind" v-model="payload" :schema="schema.properties.payload" :root="schema" :lookups="lookups" label="明确登记原资料" />
      <el-checkbox v-if="registryKind==='person_account'" v-model="accountReviewed">已明确审阅：该真实账号只关联所选同一自然人，永久关联不可按业务撤销，不把账号角色当岗位资格。</el-checkbox>
      <p v-if="registryKind==='room_alias'">命名空间和原文字必须明确，空白及大小写保持原样。旧执行记录映射须提供确切原记录并由服务器核对原房间文字，不自动猜配。</p>
    </template><template #footer><el-button @click="closeCreate">关闭</el-button><el-button type="primary" :disabled="!createValid||loading" @click="create">保存明确登记</el-button></template></el-dialog>
    <el-dialog :model-value="!!action" title="独立资源声明治理" width="min(760px,94vw)" @update:model-value="value=>!value&&closeAction()"><p>原声明 {{ selected?.registry_record_id }}，版本 {{ selected?.governance?.revision }}。审核不产生实际预约或岗位资格。</p><el-input v-model="basis" aria-label="本次资源声明治理依据" type="textarea" :rows="5" placeholder="至少20个非空白字符；撤销最多1000字符，审核最多4000 UTF-8字节" /><template #footer><el-button @click="closeAction">关闭</el-button><el-button type="primary" :disabled="!(action==='revoke'?surgeryRevokeBasis(basis):surgeryBasis(basis))||loading" @click="govern">保存本次明确治理</el-button></template></el-dialog>
  </section>
</template>

<script setup>
import {computed,onActivated,onBeforeUnmount,onDeactivated,ref,watch} from 'vue';
import {useStore} from 'vuex';
import SurgeryFields from './SurgeryFields.vue';
import {supportHash,supportId} from '@/api/inpatientSupport';
import {getSurgeryRegistry,getCompleteSurgeryRegistry,getSurgeryRegistryRecord,createSurgeryRegistry,reviewSurgeryRegistry,revokeSurgeryRegistry,getSurgeryIdentityDirectories,surgeryRegistryKinds,surgerySourceStates,surgeryPositive,surgeryBasis,surgeryRevokeBasis,surgeryFormSchema,surgeryRequestValid,verifySurgeryRegistry,verifySurgeryTransition} from '@/api/ai/surgerySources';
const props=defineProps({poolId:{type:String,default:null},active:{type:Boolean,default:true}}),emit=defineEmits(['registry-changed','pool-selected','invalidate']),store=useStore();
const rows=ref([]),total=ref(0),page=ref(1),registryKind=ref('pool'),selected=ref(null),error=ref(''),loading=ref(false),creating=ref(false),payload=ref({}),accountReviewed=ref(false),directories=ref(null),cssdKeyword=ref(''),resources=ref([]),pools=ref([]),action=ref(null),basis=ref('');let epoch=0,alive=true,wasDeactivated=false;
const roles=computed(()=>store.getters['user/permissions']||[]),allowed=computed(()=>props.active&&!!store.state.user.accessToken&&roles.value.includes('super_admin')),schema=computed(()=>surgeryFormSchema('RegistryCreate',registryKind.value));
const lookups=computed(()=>{const relevant=resources.value.filter(r=>registryKind.value==='person_account'?r.resource_kind==='person':registryKind.value==='room_alias'?r.resource_kind==='room':true);return{...(directories.value||{}),resource_id:relevant.map(r=>({value:r.resource_id,label:r.resource_kind+' · '+r.resource_id})),pool_id:pools.value.filter(r=>r.governance?.status==='published'&&r.eligible_for_new_use).map(r=>({value:r.pool_id,label:'原资源池 · '+r.pool_id}))};});
const createValid=computed(()=>allowed.value&&!!directories.value&&payload.value.kind===registryKind.value&&surgeryRequestValid('RegistryCreate',{payload:payload.value})&&(registryKind.value!=='person_account'||accountReviewed.value));
function boundary(){return JSON.stringify([store.state.user.accessToken,roles.value,props.active,props.poolId,registryKind.value]);}function ticket(){return{epoch:++epoch,boundary:boundary()};}function current(t){return alive&&allowed.value&&t.epoch===epoch&&t.boundary===boundary();}
function closeCreate(){creating.value=false;payload.value={};accountReviewed.value=false;directories.value=null;resources.value=[];pools.value=[];cssdKeyword.value='';}function closeAction(){action.value=null;basis.value='';}
function clear(){epoch++;rows.value=[];total.value=0;selected.value=null;error.value='';loading.value=false;closeCreate();closeAction();}
function failed(t,failure){if(!current(t))return;clear();error.value=failure?.message||'资源原件或当前Super范围不可用';emit('invalidate');}
function metadataValid(row,type){return row&&row.registry_kind===type&&supportId(row.registry_record_id)&&supportHash(row.content_hash)&&surgeryPositive(row.created_by)&&typeof row.eligible_for_new_use==='boolean'&&typeof row.can_review==='boolean'&&typeof row.can_revoke==='boolean'&&(!row.governance||Object.hasOwn(surgerySourceStates,row.governance.status));}
async function list(type,pageNumber=1,pageSize=20){const data=(await getSurgeryRegistry(type,{page:pageNumber,page_size:pageSize})).data;if(!data||!Array.isArray(data.items)||!Number.isSafeInteger(data.total)||data.total<0||data.page!==pageNumber||data.page_size!==pageSize||data.items.length>pageSize||data.items.some(r=>!metadataValid(r,type)))throw new Error('资源登记定位目录与实际类型或分页不一致');return data;}
async function load(){clear();if(!allowed.value)return;const t=ticket();loading.value=true;try{const data=await list(registryKind.value,page.value);if(current(t)){rows.value=data.items;total.value=data.total;}}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
async function inspect(row){selected.value=null;closeAction();const t=ticket();loading.value=true;try{const value=(await getSurgeryRegistryRecord(registryKind.value,row.registry_record_id)).data;if(!current(t))return;if(value?.registry_record_id!==row.registry_record_id||value.content_hash!==row.content_hash||!await verifySurgeryRegistry(value,registryKind.value,{auditOnly:true}))throw new Error('完整登记原件或当前父件与所选记录不一致');if(current(t))selected.value=value;}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
async function beginCreate(){if(!allowed.value)return;closeCreate();selected.value=null;const t=ticket();loading.value=true;try{const [d,r,p]=await Promise.all([getSurgeryIdentityDirectories(),getCompleteSurgeryRegistry('resource'),getCompleteSurgeryRegistry('pool')]);if(!current(t))return;directories.value=d;resources.value=r;pools.value=p;payload.value={kind:registryKind.value};creating.value=true;}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
async function readDirectories(){if(!creating.value)return;const t=ticket();loading.value=true;try{const d=await getSurgeryIdentityDirectories(cssdKeyword.value);if(current(t))directories.value=d;}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
async function create(){if(!createValid.value)return;const body={payload:JSON.parse(JSON.stringify(payload.value))},t=ticket();loading.value=true;try{const value=(await createSurgeryRegistry(registryKind.value,body)).data;if(!current(t))return;if(!await verifySurgeryRegistry(value,registryKind.value,{auditOnly:true})||value.governance&&value.governance.status!=='draft')throw new Error('新登记未返回一致的完整原件或初始草稿');if(!current(t))return;closeCreate();selected.value=value;rows.value=[value];total.value=1;emit('registry-changed',{registry_kind:registryKind.value,registry_record_id:value.registry_record_id});}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
function beginAction(value){if(!selected.value||(value==='revoke'?selected.value.can_revoke!==true:selected.value.can_review!==true))return;action.value=value;basis.value='';}
async function govern(){const original=selected.value,value=action.value;if(!original||!(value==='revoke'?surgeryRevokeBasis(basis.value):surgeryBasis(basis.value))||(value==='revoke'?original.can_revoke!==true:original.can_review!==true))return;const body={expected_revision:original.governance.revision,expected_content_hash:original.content_hash,basis_note:basis.value,...(value==='revoke'?{}:{decision:value})},t=ticket();loading.value=true;try{const data=(await(value==='revoke'?revokeSurgeryRegistry:reviewSurgeryRegistry)(registryKind.value,original.registry_record_id,body)).data;if(!current(t))return;if(!await verifySurgeryRegistry(data,registryKind.value,{auditOnly:true})||!await verifySurgeryTransition(data,original,value,body,{registryKind:registryKind.value}))throw new Error('资源治理回执不对应本次原件、版本或明确依据');if(!current(t))return;closeAction();selected.value=data;rows.value=rows.value.map(row=>row.registry_record_id===data.registry_record_id?data:row);emit('registry-changed',{registry_kind:registryKind.value,registry_record_id:data.registry_record_id});}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
watch([()=>store.state.user.accessToken,()=>JSON.stringify(roles.value),()=>props.active,()=>props.poolId,registryKind],()=>{page.value=1;clear();emit('invalidate');load();},{flush:'sync',immediate:true});
onActivated(()=>{if(wasDeactivated){wasDeactivated=false;load();}});onDeactivated(()=>{wasDeactivated=true;clear();emit('invalidate');});onBeforeUnmount(()=>{alive=false;clear();emit('invalidate');});
</script>

<style scoped>
p{line-height:1.7;overflow-wrap:anywhere}article{margin-top:16px;border:1px solid #dcdfe6;padding:16px}.el-pagination{margin:12px 0}.el-checkbox{height:auto;white-space:normal}
</style>
